package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner has the same last name and the same address (compared
 * case-insensitively with collapsed whitespace) as an existing owner, i.e. a shared household, and
 * the request did not opt in via {@code sharesHousehold}. Carries the offending last name and
 * address so the {@link ExceptionControllerAdvice} can report them to the client, which answers with
 * a 409 Conflict.
 */
public class DuplicateHouseholdException extends RuntimeException {

    private final transient String lastName;

    private final transient String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("Household already in use: " + lastName + ", " + address);
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}
